def _restore_source_text(origin, text, root):
    import hashlib
    frozen = [row for row in _SOURCE_INVERSES if row[0] == origin]
    encoded = text.encode('utf-8')
    whole = next((pin for pin in _SOURCE_WHOLE_PINS if pin[0] == origin), None)
    if whole is None:
        return text
    valid = len(encoded) == whole[1] and hashlib.sha256(encoded).hexdigest() == whole[2]
    _source_validity.append(valid)
    if not valid:
        return ''
    parts = {}
    for fragment in SOURCE_FRAGMENTS[-3:]:
        if fragment['source'] != origin:
            continue
        carrier = root / fragment['destination']
        raw = carrier.read_bytes() if carrier.is_file() else b''
        if origin == 'source/ui/availability.d':
            valid = (len(raw) == 4074 and hashlib.sha256(raw).hexdigest() ==
                'de05d3d31226b4e0a0f1dea8248dbea3278c5a6f6eedc4698f7dc5520da617ad')
            _source_validity.append(valid)
            if not valid:
                return ''
        part, matches = _original_fragment(raw.decode('utf-8'), fragment)
        _source_validity.append(matches == 1)
        if matches != 1:
            return ''
        parts[origin] = part.encode('utf-8')
    for _, offset, physical, original in reversed(frozen):
        before, after = physical.encode('utf-8'), original.encode('utf-8')
        valid = encoded[offset:offset + len(before)] == before and offset <= len(encoded)
        _source_validity.append(valid)
        if not valid:
            return ''
        if origin in parts and after:
            actual = parts[origin]
            if origin == 'source/ui/availability.d':
                after = actual[:179] if len(after) == 179 else actual[180:]
            else:
                _source_validity.append(actual == after)
                if actual != after:
                    return ''
                after = actual
        encoded = encoded[:offset] + after + encoded[offset + len(before):]
    valid = len(encoded) == whole[3] and hashlib.sha256(encoded).hexdigest() == whole[4]
    _source_validity.append(valid)
    return encoded.decode('utf-8') if valid else ''

